def find_year(abbr):
    base = 1989
    year_length = len(abbr) - 4
    year_str = abbr[3:3 + year_length]
    year = int(year_str)
    if year_length == 1:
        return base + year
    elif year_length == 2:
        return base + 100 + year
    else:
        return base + 10000 + year

n = int(input())
for _ in range(n):
    abbr = input()
    print(find_year(abbr))
